let mime = ($binary.audio.mimeType || 'audio/wav').toLowerCase();
if (mime.includes('wav')) mime = 'audio/wav';
else if (mime.includes('mpeg') || mime.includes('mp3')) mime = 'audio/mp3';
else if (mime.includes('ogg')) mime = 'audio/ogg';
else if (mime.includes('flac')) mime = 'audio/flac';
else if (mime.includes('aac')) mime = 'audio/aac';
return { json: { b64: buf.toString('base64'), mime } };

const sessionId = ($('Webhook').first().json.body || {}).sessionId || 'jarvis';
const raw = String($json.output ?? '').trim();
let data = null;
if (raw) {
  try { data = JSON.parse(raw); } catch (e) {
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) { try { data = JSON.parse(m[0]); } catch (e2) { data = null; } }
  }
}
if (!data || typeof data !== 'object' || Array.isArray(data)) {
  data = { respuesta: raw || 'Lo siento, ha ocurrido un error y no he podido procesar eso. Inténtalo de nuevo.', pantalla: '', acciones: [] };
}
const permitidos = ['abrir_web', 'buscar_google', 'buscar_youtube', 'abrir_app', 'abrir_carpeta', 'salir'];
const acciones = (Array.isArray(data.acciones) ? data.acciones : [])
  .filter(a => a && permitidos.includes(a.tipo))
  .map(a => ({ tipo: a.tipo, valor: a.valor === undefined ? '' : String(a.valor) }));
const respuesta = String(data.respuesta || '').trim() || 'Hecho.';
return { json: { respuesta, pantalla: String(data.pantalla || ''), acciones, sessionId } };

const d = $('Parsear respuesta').item.json;
let audio = null;
try {
  if ($binary && $binary.audio) {
    const buf = await this.helpers.getBinaryDataBuffer($itemIndex, 'audio');
    if (buf && buf.length > 0) audio = buf.toString('base64');
  }
} catch (e) { audio = null; }
return { json: { respuesta: d.respuesta, pantalla: d.pantalla, acciones: d.acciones, sessionId: d.sessionId, audio_base64: audio, formato: 'mp3' } };
